INSERT INTO "Category" (id,"tenantId",slug,label,"sortOrder","updatedAt")
SELECT md5(t.id || ':category:' || c.slug),t.id,c.slug,c.label,c.seq,now()
FROM "Tenant" t CROSS JOIN (VALUES
('pantyliners','Pantyliners',0),('sanitary-pads','Sanitary Pads',1),
('incontinence-pads','Light Incontinence',2),('period-pants','Period Pants',3)
) c(slug,label,seq) WHERE t.slug='kawada'
ON CONFLICT ("tenantId",slug) DO NOTHING;

INSERT INTO "Product" (id,"tenantId","categoryId",slug,model,name,"nameZh",description,i18n,specs,"imagePath","sortOrder","updatedAt")
SELECT md5(t.id || ':product:' || (item->>'slug')),t.id,c.id,item->>'slug',item->>'name',item->>'name',
item->>'zh',item->>'description',jsonb_build_object('es',jsonb_build_object('name',item->>'es')),
item->'specs',item->'images'->0->>'url',seq,now()
FROM kawada_import JOIN "Tenant" t ON t.slug='kawada'
JOIN "Category" c ON c."tenantId"=t.id AND c.slug=item->>'category'
ON CONFLICT ("tenantId",slug) DO UPDATE SET
specs=excluded.specs || coalesce("Product".specs,'{}'::jsonb),
description=coalesce("Product".description,excluded.description),
"nameZh"=coalesce("Product"."nameZh",excluded."nameZh"),
i18n=excluded.i18n || coalesce("Product".i18n,'{}'::jsonb),
"imagePath"=coalesce("Product"."imagePath",excluded."imagePath");

INSERT INTO "ProductImage" (id,"productId","imagePath",alt,"sortOrder")
SELECT md5(p.id || ':' || (img->>'url')),p.id,img->>'url',img->>'alt',
coalesce((SELECT max("sortOrder")+1 FROM "ProductImage" WHERE "productId"=p.id),0)+n
FROM kawada_import JOIN "Tenant" t ON t.slug='kawada'
JOIN "Product" p ON p."tenantId"=t.id AND p.slug=item->>'slug'
CROSS JOIN LATERAL jsonb_array_elements(item->'images') WITH ORDINALITY AS images(img,n)
WHERE NOT EXISTS (SELECT 1 FROM "ProductImage" g WHERE g."productId"=p.id AND g."imagePath"=img->>'url');
DROP TABLE kawada_import;
COMMIT;
